use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fmt::Write,fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/partial-windows175";
const Z:&str="/home/ubuntu/src/zk-tools/zopro";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-partial-windows175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn files(root:&Path,dir:&Path,out:&mut Vec<PathBuf>){for entry in fs::read_dir(dir).unwrap(){let p=entry.unwrap().path();if p.is_dir(){files(root,&p,out);}else{out.push(p.strip_prefix(root).unwrap().to_path_buf());}}}
fn main(){
    let r=Path::new(R);let z=Path::new(Z);let d=Path::new(D);fs::create_dir_all(d.join("source")).unwrap();
    let mut pins=read(r.join("pins.json")).as_object().unwrap().iter().map(|(p,h)|(p.clone(),h.as_str().unwrap().to_string())).collect::<BTreeMap<_,_>>();
    for(p,h)in &pins{assert_eq!(hash(p),*h);}
    let audit=read(r.join("setup-audit.json"));assert_eq!(audit["production_files_verified"],175);assert_eq!(audit["frozen_files_recovered"],175);
    let result=read(r.join("runs/result.json"));assert_eq!(result["status"],"complete");assert_eq!(result["steps"].as_array().unwrap().len(),4);
    for step in ["compile-tests","test-sharing-model","compile-probe","count-two-fixtures"] {
        let p=r.join("runs").join(step);let exit=read(p.join("exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);
        assert_eq!(hash(p.join("stdout.log")),exit["stdout_sha256"]);assert_eq!(hash(p.join("stderr.log")),exit["stderr_sha256"]);
    }
    let tests=read(r.join("runs/test-sharing-model/tests.json"));assert_eq!(tests["passed_tests"].as_array().unwrap().len(),4);
    let stdout=fs::read_to_string(r.join("runs/count-two-fixtures/stdout.log")).unwrap();
    let rows=stdout.lines().filter_map(|l|l.strip_prefix("ROW ")).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();assert_eq!(rows.len(),2);
    let complete=serde_json::from_str::<Value>(stdout.lines().find_map(|l|l.strip_prefix("COMPLETE ")).unwrap()).unwrap();
    assert_eq!(complete["necessary_opportunity_gate"],true);assert_eq!(complete["performance_claim"],false);assert_eq!(complete["new_solver_calls"],0);assert_eq!(complete["SDK_requests"],0);assert_eq!(complete["new_independent_exports"],0);
    for(row,shape)in rows.iter().zip(["1x2","2x2"]) {
        assert_eq!(row["shape"],shape);let u=|k:&str|row[k].as_u64().unwrap();let count=|k:&str|row["counts"][k].as_u64().unwrap();
        let m=u("selected_pairs");let removed=u("whole_duplicate_removed_arrivals")+u("genuine_partial_removed_arrivals");
        assert_eq!(m,u("whole_duplicate_pairs")+u("genuine_partial_pairs"));
        assert_eq!(removed,count("removed_arrivals"));assert_eq!(removed,count("baseline_arrivals")-count("after_arrivals"));
        assert_eq!(removed,count("baseline_generic_bucket_tree_additions")-count("after_generic_bucket_tree_additions"));
        assert_eq!(removed-m,count("generic_net_additions_saved"));assert_eq!(m,count("charged_auxiliary_point_additions"));
        assert_eq!(u("genuine_partial_generic_net_additions_saved"),u("genuine_partial_removed_arrivals")-u("genuine_partial_pairs"));
        assert_eq!(u("signed_column_comparisons"),22*u("pair_comparisons"));
        let hist=row["shared_columns_histogram"].as_object().unwrap();assert_eq!(hist.values().map(|v|v.as_u64().unwrap()).sum::<u64>(),m);
        assert_eq!(hist.iter().map(|(k,v)|k.parse::<u64>().unwrap()*v.as_u64().unwrap()).sum::<u64>(),removed);
        assert_eq!(u("hypothetical_runtime_extra_requested_payload_bytes"),4*u("post_group_rows")+140*m);
        assert!(u("largest_tile")<=64);assert!(m<=u("post_group_rows")/2);assert!(u("genuine_partial_pairs")>0);
        let net=(removed-m)as f64/count("baseline_generic_bucket_tree_additions")as f64;
        assert!((net-row["counts"]["generic_net_fraction"].as_f64().unwrap()).abs()<1e-15);
    }
    let snapshot_path=z.join("docs/benchmarks/2026-10-30-current-bench-snapshot175/data.json");let snapshot=read(&snapshot_path);
    assert_eq!(snapshot["accepted_original8_CPU10x"],0);assert_eq!(snapshot["historical_distinct_Gnark_ledger"],25231);assert_eq!(snapshot["rows"].as_array().unwrap().len(),9);
    for row in snapshot["rows"].as_array().unwrap().iter().take(8) {
        let ratio=&row["M5_reference_and_local_ratios"];let ms=row["local_accepted"]["ms"].as_f64().unwrap();assert_eq!(ratio["accepted_ms"],row["local_accepted"]["ms"]);
        for (reference,speed) in [("cpu_reference_ms","cpu_speedup"),("metal_reference_ms","metal_speedup")] {
            assert!((ratio[reference].as_f64().unwrap()/ms-ratio[speed].as_f64().unwrap()).abs()<1e-12);
        }
    }
    let history=["docs/benchmarks/2026-10-21-ryzen-research/global-window-search-floor/README.md","docs/benchmarks/2026-10-27-parallel-scalar-groups/artifacts/research-audit.md","docs/benchmarks/2026-10-25-sparse-grouped-g2/README.md","docs/benchmarks/2026-10-25-sparse-grouped-g2-remaining/README.md","docs/benchmarks/2026-10-25-borrowed-grouped-g2/README.md"];
    for p in history{let p=z.join(p);pins.insert(p.display().to_string(),hash(p));}
    pins.insert(snapshot_path.display().to_string(),hash(&snapshot_path));
    let own=["probe.rs","split.rs","setup.rs","design.md","history-audit.md","publish.rs"];
    for file in own{fs::copy(r.join(file),d.join("source").join(file)).unwrap();pins.insert(r.join(file).display().to_string(),hash(r.join(file)));}
    for file in ["plan.json","pins.json","setup-audit.json","setup.log","workflow.log","initial-perf-dispatch.log"]{pins.insert(r.join(file).display().to_string(),hash(r.join(file)));}
    save(d.join("accepted-rows.json"),&snapshot["rows"]);
    save(d.join("data.json"),&json!({"rows":rows,"completion":complete,"workflow":result,"source_audit":audit,
        "tests":tests,"native_kernel_selected":false,"native_integration_decision":"Not selected: small generic savings relative to the measured count of required search comparisons; no native runtime claim.",
        "prior_related_work_was_already_reviewed":true,"new_performance_captures":0,"accepted_original8_CPU10x":0,
        "all_nine_accepted_rows":"accepted-rows.json","proof_ledger":25231}));
    save(d.join("source-hashes.json"),&json!(pins));
    let mut receipt_files=Vec::new();files(r,&r.join("runs"),&mut receipt_files);
    receipt_files.extend(["setup.log","workflow.log","initial-perf-dispatch.log","initial-setup/setup.rs","initial-setup/setup.log","plan.json","pins.json","setup-audit.json"].map(PathBuf::from));receipt_files.sort();
    let archive=d.join("workflow-receipts.tar.gz");let status=Command::new("tar").arg("-czf").arg(&archive).arg("-C").arg(r).args(&receipt_files).status().unwrap();assert!(status.success());
    let listing=Command::new("tar").arg("-tzf").arg(&archive).output().unwrap();assert!(listing.status.success());
    let names=String::from_utf8(listing.stdout).unwrap().lines().map(str::to_string).collect::<BTreeSet<_>>();
    assert_eq!(names,receipt_files.iter().map(|p|p.display().to_string()).collect::<BTreeSet<_>>());
    for name in &receipt_files {let out=Command::new("tar").arg("-xOf").arg(&archive).arg(name).output().unwrap();assert!(out.status.success());assert_eq!(out.stdout,fs::read(r.join(name)).unwrap());}
    let mut md=String::from("# Partial scalar-window sharing: count screen\n\nThis restricted local-pair layout is not selected for native integration. Its algebra and necessary opportunity gate pass, but generic G2 bucket-tree additions decrease only **0.174% on 1×2** and **0.033% on 2×2**, with roughly 0.95 million and 0.91 million row-pair comparisons. No prover source or accepted timing changes.\n\n## Method and scope\n\nIndependently implement a disjoint-pair restriction of digit reuse described in [Hrabar’s 2026 Waterloo thesis](https://uwspace.uwaterloo.ca/items/43cc12b9-cb03-42bd-a01c-4b0ed5e12403), section 5.2. After the current whole-scalar grouping decision, split each existing point-range half into consecutive tiles of at most 64 rows. Examine every original-row pair across 22 signed Phi2/Booth columns. Prefer more shared nonzero digits, then lower indices; each original row participates at most once. Remove its common digits from both residual rows and feed them once with the derived sum Pi+Pj. There is no recursive, negative, cross-tile or cross-part pairing. This is not a reproduction of the thesis’s full CRLC algorithm or published measurements.\n\nThe two saved fixture populations already have independent complete-MSM oracle receipts. Their hashes, canonical fields, on-curve inputs and scalar representations are rechecked. The accepted grouping policy declines 1×2 and admits 2×2 (52,274 rows become 28,852). Grouped point cancellation is not determined by scalar metadata and is not modeled. The admitted grouping case assumes its existing reservation is available; this is not a pressure test.\n\n## Counts\n\n| Shape | Post-group rows | Selected / genuine partial pairs | Generic bucket-tree additions before | Net saved after derived sums | Net reduction | Row-pair comparisons | Proposed extra payload KiB |\n|---|---:|---:|---:|---:|---:|---:|---:|\n");
    for row in &rows {let u=|k:&str|row[k].as_u64().unwrap();let c=&row["counts"];
        writeln!(md,"| {} | {} | {} / {} | {} | {} | {:.6}% | {} | {:.3} |",row["shape"].as_str().unwrap(),u("post_group_rows"),u("selected_pairs"),u("genuine_partial_pairs"),c["baseline_generic_bucket_tree_additions"],c["generic_net_additions_saved"],100.*c["generic_net_fraction"].as_f64().unwrap(),u("pair_comparisons"),u("hypothetical_runtime_extra_requested_payload_bytes")as f64/1024.).unwrap();
    }
    md.push_str("\nPrimary savings split into 747 additions from 37 whole-duplicate pairs and 179 from 178 genuine partial pairs. The 2×2 result has 181 additions saved from 180 genuine partial pairs and no remaining whole-duplicate pairs. The layout examines 20,845,792 and 19,972,700 signed column pairs. Occupied magnitude buckets and indexed-top signed bins stay occupied; this supports the generic noncancelling arrival/tree-addition proxy. One derived point addition is charged per selected pair. Actual curve exceptions, inversions, borrowed queues, tree topology, phi cost, complete-query finishing and wall time are not modeled. These percentages are not predicted proof-time gains or rigorous latency ceilings.\n\nThe count gate has no minimum percentage threshold and **passes**. Choosing not to build this layout is a separate engineering decision based on its small work reduction and search volume. Neither a native slowdown nor the impossibility of other clustering designs is established. No timing sweep or successful test repetition is performed.\n\n## Correctness and memory\n\nFour standalone native-model tests pass. They cover 8,195 deterministic/edge canonical scalars plus signed 126-bit component boundaries; full/partial/negative/zero digits; inactive identities; empty, odd, tail and partition-boundary populations; and deterministic disjoint selection. Each selected rewrite conserves every original signed coefficient exactly. Both fixture populations reconstruct their Phi components and full Fr scalar exactly. Two independent Fr-token populations check every output bucket/sign bin and the weighted full sum against the original scalar dot product. There are 82,432 checked bins per population per token stream. These field-token and symbolic checks do not qualify a new real-curve kernel. Unchanged production field/core suites are inherited, not rerun.\n\nA hypothetical runtime layout needs 4N residual-mask bytes plus 12M pair-record bytes and 128M derived-point bytes: 150,456  / 140,608 requested bytes for these two populations. It borrows original key points. This excludes Vec headers/capacity rounding, tile and normalization scratch, allocator overhead, stacks and existing query workspace. No production layout, admission/release behavior, minimum RAM, mobile, huge-key or concurrent-proof feasibility is qualified. The count helper’s allocations are analysis storage, not prover RSS. Masked residuals are kept as explicit digits in the model; ordinary scalar recoding is not assumed to preserve them.\n\n## Related work and next selection\n\nA wider history search after the count located older Hrabar reviews and negative global-window search results. This report adds a restricted current-fixture census; it does not discover the thesis anew or reopen the old serialized search. Sparse whole-scalar grouping with singleton references and repeated-only point sums was also already implemented and measured, including a borrowed revision; its original full gate failed. Neither candidate should be rerun unchanged. [History audit](source/history-audit.md).\n\nReturn to retained full threaded caller/SDK profiles and select a distinct cost-removal mechanism before building another reuse or arithmetic kernel. These counts do not explain the AWS/Aeglos gap.\n\n## Accepted proof results, unchanged\n\nThe original all-eight 10× M5 CPU objective remains **0/8**. CPU/Metal columns use supplied M5 reference timings, not fresh Apple measurements. Local accepted results are from the saved 32-worker campaign; merge54 has no supplied M5 reference.\n\n| Shape | Local ms | Peak RSS MiB | M5 CPU ms / speedup | M5 Metal ms / speedup | CPU10× target ms |\n|---|---:|---:|---:|---:|---:|\n");
    for row in snapshot["rows"].as_array().unwrap(){let local=&row["local_accepted"];let ratio=&row["M5_reference_and_local_ratios"];
        if ratio.is_object(){writeln!(md,"| {} | {:.6} | {:.2} | {:.0} / {:.2}× | {:.0} / {:.2}× | {:.1} |",row["shape"].as_str().unwrap(),local["ms"].as_f64().unwrap(),local["max_RSS_MiB"].as_f64().unwrap(),ratio["cpu_reference_ms"].as_f64().unwrap(),ratio["cpu_speedup"].as_f64().unwrap(),ratio["metal_reference_ms"].as_f64().unwrap(),ratio["metal_speedup"].as_f64().unwrap(),ratio["required_ms_for_CPU10x"].as_f64().unwrap()).unwrap();}
        else{writeln!(md,"| {} | {:.6} | {:.2} | — | — | — |",row["shape"].as_str().unwrap(),local["ms"].as_f64().unwrap(),local["max_RSS_MiB"].as_f64().unwrap()).unwrap();}
    }
    md.push_str("\nLatest retained C7a 1×2: Zopro 11.915591 ms at 32 workers versus Aeglos 7.959184 ms at 96 workers, best tested settings in that campaign. This is a configuration-specific comparison. All nine local/AWS rows, engine worker counts, RSS and original eight reference ratios are retained exactly in [accepted rows](accepted-rows.json); see the [complete snapshot](../2026-10-30-current-bench-snapshot175/README.md). No new AWS, CPU profile, performance capture, witness solve, SDK request or independent proof export occurs. Distinct verified-export ledger remains 25,231.\n\n## Receipts\n\nA source-pinned Rust xtask workflow completes compile-tests, four model tests, compile-probe and count-two-fixtures once, with 427 input pins. All 175 production sources match the accepted manifest; the reused library snapshot recovers those same sources after removing only two diagnostic export suffixes. Copied grouping, Phi-split and Booth functions match their qualified source checks. Every command exit and stdout/stderr hash is checked.\n\nInitial preparation incorrectly read a binary manifest member as UTF-8 and stopped before a workflow existed. The original helper/log is retained; the correction hashes bytes. An initial invocation selected xtask’s perf subcommand instead of workflow and was rejected during configuration parsing, before any step/output directory. The unchanged plan then completed via workflow. No successful native command or count was repeated.\n\n[Machine-readable counts](data.json), [declared design](source/design.md), [model source](source/probe.rs), [setup source](source/setup.rs), [publisher](source/publish.rs), [source hashes](source-hashes.json), [exact workflow receipts](workflow-receipts.tar.gz), [checksums](SHA256SUMS). Raw fixture points/scalars, unblinded query results, libraries and executables are excluded.\n");
    fs::write(d.join("README.md"),md).unwrap();
    let mut published=Vec::new();files(d,d,&mut published);published.retain(|p|p!=Path::new("SHA256SUMS"));published.sort();
    let sums=published.iter().map(|p|format!("{}  {}\n",hash(d.join(p)),p.display())).collect::<String>();fs::write(d.join("SHA256SUMS"),sums).unwrap();
    println!("Published {} files; {} archive members, {} pins, 2 count rows, 9 unchanged accepted rows; no runtime rerun",published.len()+1,receipt_files.len(),pins.len());
}
